-- LiteShop 微服务管理前端联调测试数据
-- 文件：09_seed_ui_test_data.sql
-- 适用：MySQL 8.0，已完成新版多租户表结构及基础菜单、会员等级初始化的数据库。
-- 使用：在同一个 MySQL 实例上，以 UTF-8 打开本文件，执行“整个 SQL 脚本”。
-- 需要支持 DELIMITER 的客户端（如 MySQL CLI / Navicat / DBeaver 脚本模式），
-- 并具有五个业务库的读写权限和本脚本辅助存储过程的 CREATE ROUTINE / ALTER ROUTINE / EXECUTE 权限。
-- 请使用独立连接执行；辅助过程的创建和删除属于 DDL，会提交连接上先前尚未提交的事务。
--
-- 本脚本尚未执行。只新增独立测试租户及其数据；不会重建表、重置原账号或修改已有菜单。
-- 业务写入在一个事务内完成，任一 SQL 错误或警告均回滚，测试 ID/编码冲突时也回滚。
-- 此脚本为一次性导入；重复执行会明确报错，不覆盖已经导入或编辑过的数据。
-- 辅助过程 ui_seed_20260903_import 仅用于此次导入，脚本结束后删除。
--
-- 数据：2 商户、16 账号、4 门店、12 分类、32 菜品及规格、24 餐桌；
--       144 订单 / 432 明细、8 优惠券 / 14 领券 / 2 核销；
--       4 抽奖活动 / 8 奖品 / 8 记录、30 配置、8 轮播图、4 打印模板。
-- 订单日期相对执行当天生成，包含近 30 天已完成订单及当前各状态自提订单。
-- 金额、明细、优惠券库存、抽奖库存、积分和余额记录相互对应。
-- 历史已支付订单为现金模拟记录，没有真实支付流水；门店为线下收银模式，打印关闭。
-- SQL 不生成 Redis 餐桌会话、支付超时队列或第三方流水，相关流程请在界面新建订单测试。
-- 图片使用 placehold.co 在线占位图，可在管理界面替换；菜品图片/标签遵循当前前端的逗号分隔格式。
--
-- 所有测试账号密码：Admin@123456（BCrypt 与已有开发种子一致）。
-- test_admin             -> 同账号登录后选择“联调测试·青禾餐饮”或“联调测试·橙里轻食”
-- test_a_manager         -> 青禾一号店；test_a_staff -> 青禾二号店
-- test_b_manager         -> 橙里一号店；test_b_staff -> 橙里二号店
-- test_a_disabled / test_b_disabled -> 停用店员，用于验证禁止登录
-- test_a_member1..4 / test_b_member1..4 -> USER 消费者账号，不是管理后台账号
-- 租户 ID：910001 / 910002；编码：UI_TEST_A / UI_TEST_B。
-- 两个租户使用相同门店编码 UI_STORE_01 / UI_STORE_02、配置键和 test_admin 账号，验证隔离。
-- 平台管理员继续使用原有账号；本脚本不新增 SUPER_ADMIN。
-- 执行后重新登录以加载账号权限；如果此前访问过这些租户的配置，刷新对应配置缓存。
-- 不要为导入本测试数据而重跑 01~06 建表脚本或 07 升级脚本。

SET NAMES utf8mb4;
USE `liteshop_user`;

DROP PROCEDURE IF EXISTS `liteshop_user`.`ui_seed_20260903_import`;
DELIMITER $$
CREATE PROCEDURE `liteshop_user`.`ui_seed_20260903_import`()
SQL SECURITY INVOKER
MODIFIES SQL DATA
BEGIN
  DECLARE v_now DATETIME;
  DECLARE v_count INT DEFAULT 0;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION, SQLWARNING
  BEGIN
    ROLLBACK;
    RESIGNAL;
  END;

  -- 所有写入表必须已存在且为 InnoDB，确保跨库事务可以完整回滚。
  SELECT COUNT(*) INTO v_count
  FROM information_schema.TABLES
  WHERE ENGINE = 'InnoDB'
    AND ((TABLE_SCHEMA = 'liteshop_user' AND TABLE_NAME = 'sys_tenant')
         OR (TABLE_SCHEMA = 'liteshop_user' AND TABLE_NAME = 'sys_role')
         OR (TABLE_SCHEMA = 'liteshop_user' AND TABLE_NAME = 'sys_user')
         OR (TABLE_SCHEMA = 'liteshop_user' AND TABLE_NAME = 'sys_user_role')
         OR (TABLE_SCHEMA = 'liteshop_user' AND TABLE_NAME = 'user_points_record')
         OR (TABLE_SCHEMA = 'liteshop_user' AND TABLE_NAME = 'user_surplus_record')
         OR (TABLE_SCHEMA = 'liteshop_user' AND TABLE_NAME = 'sys_user_store')
         OR (TABLE_SCHEMA = 'liteshop_restaurant' AND TABLE_NAME = 'store_info')
         OR (TABLE_SCHEMA = 'liteshop_restaurant' AND TABLE_NAME = 'dish_category')
         OR (TABLE_SCHEMA = 'liteshop_restaurant' AND TABLE_NAME = 'dish')
         OR (TABLE_SCHEMA = 'liteshop_restaurant' AND TABLE_NAME = 'dish_spec_option')
         OR (TABLE_SCHEMA = 'liteshop_restaurant' AND TABLE_NAME = 'table_info')
         OR (TABLE_SCHEMA = 'liteshop_restaurant' AND TABLE_NAME = 'print_template')
         OR (TABLE_SCHEMA = 'liteshop_restaurant' AND TABLE_NAME = 'restaurant_order')
         OR (TABLE_SCHEMA = 'liteshop_restaurant' AND TABLE_NAME = 'restaurant_order_item')
         OR (TABLE_SCHEMA = 'liteshop_coupon' AND TABLE_NAME = 'coupon')
         OR (TABLE_SCHEMA = 'liteshop_coupon' AND TABLE_NAME = 'coupon_dish_item')
         OR (TABLE_SCHEMA = 'liteshop_coupon' AND TABLE_NAME = 'user_coupon')
         OR (TABLE_SCHEMA = 'liteshop_coupon' AND TABLE_NAME = 'verify_record')
         OR (TABLE_SCHEMA = 'liteshop_lottery' AND TABLE_NAME = 'lottery_activity')
         OR (TABLE_SCHEMA = 'liteshop_lottery' AND TABLE_NAME = 'lottery_prize')
         OR (TABLE_SCHEMA = 'liteshop_lottery' AND TABLE_NAME = 'activity_prize')
         OR (TABLE_SCHEMA = 'liteshop_lottery' AND TABLE_NAME = 'lottery_record')
         OR (TABLE_SCHEMA = 'liteshop_lottery' AND TABLE_NAME = 'user_activity_chance')
         OR (TABLE_SCHEMA = 'liteshop_config' AND TABLE_NAME = 'sys_config')
         OR (TABLE_SCHEMA = 'liteshop_config' AND TABLE_NAME = 'sys_banner')
         OR (TABLE_SCHEMA = 'liteshop_user' AND TABLE_NAME = 'sys_role_permission'));
  IF v_count <> 27 THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = '测试导入停止：所需业务表缺失或不是 InnoDB，请先核对新版数据库结构。';
  END IF;

  SELECT COUNT(*) INTO v_count FROM information_schema.COLUMNS
  WHERE TABLE_SCHEMA = 'liteshop_user'
    AND ((TABLE_NAME = 'sys_tenant' AND COLUMN_NAME = 'tenant_code')
      OR (TABLE_NAME IN ('sys_user_role', 'sys_role_permission') AND COLUMN_NAME = 'tenant_id'));
  IF v_count <> 3 THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = '测试导入停止：缺少新版 tenant_code 或关联表 tenant_id，请先完成表结构升级。';
  END IF;

  SELECT COUNT(DISTINCT permission_code) INTO v_count
  FROM liteshop_user.sys_permission
  WHERE status = 1 AND permission_code IN ('system:menu', 'system:user', 'system:role', 'system:user-store', 'restaurant:menu', 'restaurant:store', 'restaurant:category', 'restaurant:dish', 'restaurant:table', 'restaurant:order', 'restaurant:printer', 'restaurant:analysis', 'marketing:menu', 'marketing:coupon', 'marketing:lottery', 'config:menu', 'config:basic', 'config:banner');
  IF v_count <> 18 THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = '测试导入停止：基础管理菜单不完整，请核对现有 sys_permission 初始化数据。';
  END IF;

  SELECT COUNT(DISTINCT level_code) INTO v_count FROM liteshop_user.user_level
  WHERE level_code IN (1, 2, 3, 4) AND status = 1;
  IF v_count <> 4 THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = '测试导入停止：缺少 1~4 级会员配置，请核对现有 user_level 初始化数据。';
  END IF;

  START TRANSACTION;
  -- 所有日期均以执行瞬间的北京时间为基准，避免导入固定日期后看不到近期统计。
  SET v_now = DATE_ADD(UTC_TIMESTAMP(), INTERVAL 8 HOUR);

  IF EXISTS (
    SELECT 1 FROM liteshop_user.sys_tenant
    WHERE id IN (910001, 910002)
       OR tenant_code IN ('UI_TEST_A', 'UI_TEST_B')
       OR tenant_name IN ('联调测试·青禾餐饮', '联调测试·橙里轻食')
  ) THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = '测试数据已导入或 ID/编码/名称已被占用；已停止，现有数据不会被覆盖。';
  END IF;

  -- 防止目标租户 ID 下已有历史残留行，意外将其归入本次测试商户。
  IF EXISTS (
    SELECT 1 FROM `liteshop_user`.`sys_role` WHERE tenant_id IN (910001, 910002)
    UNION ALL
    SELECT 1 FROM `liteshop_user`.`sys_user` WHERE tenant_id IN (910001, 910002)
    UNION ALL
    SELECT 1 FROM `liteshop_user`.`sys_user_role` WHERE tenant_id IN (910001, 910002)
    UNION ALL
    SELECT 1 FROM `liteshop_user`.`user_points_record` WHERE tenant_id IN (910001, 910002)
    UNION ALL
    SELECT 1 FROM `liteshop_user`.`user_surplus_record` WHERE tenant_id IN (910001, 910002)
    UNION ALL
    SELECT 1 FROM `liteshop_user`.`sys_user_store` WHERE tenant_id IN (910001, 910002)
    UNION ALL
    SELECT 1 FROM `liteshop_restaurant`.`store_info` WHERE tenant_id IN (910001, 910002)
    UNION ALL
    SELECT 1 FROM `liteshop_restaurant`.`dish_category` WHERE tenant_id IN (910001, 910002)
    UNION ALL
    SELECT 1 FROM `liteshop_restaurant`.`dish` WHERE tenant_id IN (910001, 910002)
    UNION ALL
    SELECT 1 FROM `liteshop_restaurant`.`dish_spec_option` WHERE tenant_id IN (910001, 910002)
    UNION ALL
    SELECT 1 FROM `liteshop_restaurant`.`table_info` WHERE tenant_id IN (910001, 910002)
    UNION ALL
    SELECT 1 FROM `liteshop_restaurant`.`print_template` WHERE tenant_id IN (910001, 910002)
    UNION ALL
    SELECT 1 FROM `liteshop_restaurant`.`restaurant_order` WHERE tenant_id IN (910001, 910002)
    UNION ALL
    SELECT 1 FROM `liteshop_restaurant`.`restaurant_order_item` WHERE tenant_id IN (910001, 910002)
    UNION ALL
    SELECT 1 FROM `liteshop_coupon`.`coupon` WHERE tenant_id IN (910001, 910002)
    UNION ALL
    SELECT 1 FROM `liteshop_coupon`.`coupon_dish_item` WHERE tenant_id IN (910001, 910002)
    UNION ALL
    SELECT 1 FROM `liteshop_coupon`.`user_coupon` WHERE tenant_id IN (910001, 910002)
    UNION ALL
    SELECT 1 FROM `liteshop_coupon`.`verify_record` WHERE tenant_id IN (910001, 910002)
    UNION ALL
    SELECT 1 FROM `liteshop_lottery`.`lottery_activity` WHERE tenant_id IN (910001, 910002)
    UNION ALL
    SELECT 1 FROM `liteshop_lottery`.`lottery_prize` WHERE tenant_id IN (910001, 910002)
    UNION ALL
    SELECT 1 FROM `liteshop_lottery`.`activity_prize` WHERE tenant_id IN (910001, 910002)
    UNION ALL
    SELECT 1 FROM `liteshop_lottery`.`lottery_record` WHERE tenant_id IN (910001, 910002)
    UNION ALL
    SELECT 1 FROM `liteshop_lottery`.`user_activity_chance` WHERE tenant_id IN (910001, 910002)
    UNION ALL
    SELECT 1 FROM `liteshop_config`.`sys_config` WHERE tenant_id IN (910001, 910002)
    UNION ALL
    SELECT 1 FROM `liteshop_config`.`sys_banner` WHERE tenant_id IN (910001, 910002)
    UNION ALL
    SELECT 1 FROM `liteshop_user`.`sys_role_permission` WHERE tenant_id IN (910001, 910002)
  ) THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = '测试导入停止：目标租户 ID 下已有业务记录，请先核对占用情况。';
  END IF;

  -- liteshop_user.sys_tenant：2 条

  -- liteshop_user.sys_role：8 条

  -- liteshop_user.sys_user：16 条

  -- liteshop_user.sys_user_role：16 条

  -- 角色授权与 SysTenantServiceImpl 的新商户初始化规则一致。
  -- 使用现有权限定义，不写入或改动全局菜单；普通消费者不分配管理菜单。
  SELECT r.tenant_id, r.id, p.id
  FROM liteshop_user.sys_role r
  JOIN liteshop_user.sys_permission p ON p.status = 1
  WHERE r.tenant_id IN (910001, 910002)
    AND (
      (r.role_code = 'ADMIN' AND p.permission_code NOT LIKE 'platform:%')
      OR (r.role_code = 'STORE_ADMIN' AND p.permission_code LIKE 'restaurant:%')
      OR (r.role_code = 'STORE_STAFF' AND (
        p.permission_code = 'restaurant:menu'
        OR p.permission_code LIKE 'restaurant:order%'
        OR p.permission_code LIKE 'restaurant:table%'
      ))
    );

  -- liteshop_user.user_points_record：10 条

  -- liteshop_user.user_surplus_record：6 条

  -- liteshop_user.sys_user_store：6 条

  -- liteshop_restaurant.store_info：4 条

  -- liteshop_restaurant.dish_category：12 条

  -- liteshop_restaurant.dish：32 条

  -- liteshop_restaurant.dish_spec_option：32 条

  -- liteshop_restaurant.table_info：24 条

  -- liteshop_restaurant.print_template：4 条

  -- liteshop_restaurant.restaurant_order：144 条

  -- liteshop_restaurant.restaurant_order_item：432 条

  -- liteshop_coupon.coupon：8 条

  -- liteshop_coupon.coupon_dish_item：4 条

  -- liteshop_coupon.user_coupon：14 条

  -- liteshop_coupon.verify_record：2 条

  -- liteshop_lottery.lottery_activity：4 条

  -- liteshop_lottery.lottery_prize：8 条

  -- liteshop_lottery.activity_prize：16 条

  -- liteshop_lottery.lottery_record：8 条

  -- liteshop_lottery.user_activity_chance：8 条

  -- liteshop_config.sys_config：30 条

  -- liteshop_config.sys_banner：8 条

  -- 导入后的事务内核对：订单金额与明细相符，关联的会员、门店、菜品必须同租户。
  IF EXISTS (
    SELECT 1
    FROM liteshop_restaurant.restaurant_order o
    LEFT JOIN (
      SELECT order_id, SUM(price * quantity) AS gross_amount,
             SUM(discount_price) AS discount_amount, SUM(total_price) AS net_amount
      FROM liteshop_restaurant.restaurant_order_item
      WHERE tenant_id IN (910001, 910002)
      GROUP BY order_id
    ) i ON i.order_id = o.id
    JOIN liteshop_restaurant.store_info s ON s.id = o.store_id
    JOIN liteshop_user.sys_user u ON u.id = o.user_id
    WHERE o.tenant_id IN (910001, 910002)
      AND (i.order_id IS NULL OR ABS(o.total_amount - i.gross_amount) > 0.001
           OR ABS(o.discount_amount - i.discount_amount) > 0.001
           OR ABS(o.actual_amount - i.net_amount) > 0.001
           OR o.tenant_id <> s.tenant_id OR o.tenant_id <> u.tenant_id)
  ) OR EXISTS (
    SELECT 1 FROM liteshop_restaurant.restaurant_order_item i
    JOIN liteshop_restaurant.restaurant_order o ON o.id = i.order_id
    JOIN liteshop_restaurant.dish d ON d.id = i.dish_id
    WHERE i.tenant_id IN (910001, 910002)
      AND (i.tenant_id <> o.tenant_id OR i.tenant_id <> d.tenant_id OR o.store_id <> d.store_id)
  ) THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = '测试数据关联或金额核对失败，本次导入已全部回滚。';
  END IF;

  COMMIT;

  -- 只有成功提交后才会输出此结果：每商户应为 8 账号、2 门店、16 菜品、72 订单。
  SELECT t.id AS tenant_id, t.tenant_code, t.tenant_name,
    (SELECT COUNT(*) FROM liteshop_user.sys_user u WHERE u.tenant_id = t.id) AS users,
    (SELECT COUNT(*) FROM liteshop_restaurant.store_info s WHERE s.tenant_id = t.id) AS stores,
    (SELECT COUNT(*) FROM liteshop_restaurant.dish d WHERE d.tenant_id = t.id) AS dishes,
    (SELECT COUNT(*) FROM liteshop_restaurant.restaurant_order o WHERE o.tenant_id = t.id) AS orders,
    (SELECT COUNT(*) FROM liteshop_coupon.coupon c WHERE c.tenant_id = t.id) AS coupons,
    (SELECT COUNT(*) FROM liteshop_lottery.lottery_activity a WHERE a.tenant_id = t.id) AS activities
  FROM liteshop_user.sys_tenant t
  WHERE t.id IN (910001, 910002)
  ORDER BY t.id;
END$$
DELIMITER ;

CALL `liteshop_user`.`ui_seed_20260903_import`();
DROP PROCEDURE IF EXISTS `liteshop_user`.`ui_seed_20260903_import`;

-- 成功后用 test_admin / Admin@123456 登录管理前端，在第二步选择测试商户。
